fn session_ctx(session: &Arc<MemorySession>) -> RunContext<()> {
    RunContext::new(
        Arc::new(()),
        Arc::clone(session) as Arc<dyn Session>,
        HookRegistry::new(),
        TracerHandle::default(),
        CancellationToken::new(),
    )
    .with_permission_policy(Arc::new(DeferB))
