/// The call id of the transfer call from `path[i]` to `path[i + 1]`.
fn transfer_id(i: usize) -> String {
    format!("t{}", i + 1)
}

fn transfer_turn(call_id: &str, target: &str) -> Vec<ModelEvent> {
